from promote_l271_l300_common import make_lesson, run_batch
SM="src.web.google-sre-monitoring"; EB="src.web.google-sre-error-budget-policy"; IM="src.web.google-sre-incident-management"; GX="src.web.gx-data-quality-use-cases"
SML="1_Nguon/Web/SRC-GOOGLE-SRE-MONITORING"; EBL="1_Nguon/Web/SRC-GOOGLE-SRE-ERROR-BUDGET-POLICY"; IML="1_Nguon/Web/SRC-GOOGLE-SRE-INCIDENT-MANAGEMENT"; GXL="1_Nguon/Web/SRC-GX-DATA-QUALITY-USE-CASES"
def a(*items): return tuple((x.split("|",1)[0],x.split("|",1)[1]) for x in items)
LESSONS=(
make_lesson(286,"Lesson_286-data-sli-and-slo-design","Data SLI and SLO design","wiki.data-quality.sli-slo-design","Thiết kế data SLI/SLO thế nào để phản ánh trải nghiệm consumer thay vì sức khỏe job nội bộ?",(SM,GX),(SML,GXL),a(
"Consumer journey|Bắt đầu từ decision/report/model mà dữ liệu phục vụ, critical assets và thời điểm consumer thực sự cần.","SLI ratio|Định nghĩa good events trên eligible events hoặc good intervals trên valid intervals; numerator/denominator phải query lại được.","Data signals|Freshness, completeness, correctness proxy, schema usability và availability có thể là SLIs riêng, không trộn thành điểm bí ẩn.","SLO window|Target, rolling/calendar window, exclusions và low-traffic handling phải ghi cùng policy.","Measurement architecture|Probe ở publication/consumer boundary, lưu late corrections và đo cả monitoring gaps.","Review and ownership|SLO có owner, stakeholder agreement, review cadence và trigger đổi khi use case hoặc source authority thay.")),
make_lesson(287,"Lesson_287-low-noise-alerting-and-the-error-budget","Low-noise alerting and the error budget","wiki.data-quality.alerting-error-budget","Alert và error budget được nối với hành động thế nào để giảm noise nhưng không che user harm?",(SM,EB),(SML,EBL),a(
"Page criteria|Page chỉ khi cần hành động khẩn cấp để giảm harm; ticket và dashboard dành cho công việc không tức thời.","Budget math|Error budget bằng phần không đạt SLO trên đúng eligible population/window, không phải số alert.","Burn-rate view|Fast burn bắt sự cố lớn sớm; slow burn phát hiện suy giảm kéo dài, cả hai cần minimum traffic.","Dedup and routing|Group theo incident/failure domain, route tới owner có runbook; suppress phải có expiry và audit.","Policy action|Budget state phải kích hoạt hành động đã thỏa thuận như freeze, reliability work hay review, không dùng để phạt.","Noise evaluation|Đo actionable rate, duplicates, acknowledged-without-action, missed incidents và operator load theo thời gian.")),
make_lesson(288,"Lesson_288-the-incident-lifecycle-eight-steps","The incident lifecycle - eight steps","wiki.data-quality.incident-lifecycle","Tám bước incident lifecycle giữ containment, communication, evidence và learning liền mạch như thế nào?",(IM,),(IML,),a(
"Detect and declare|Xác nhận user impact, severity và scope ban đầu; declare sớm với uncertainty tốt hơn xử lý ngầm.","Assign roles|Incident commander, operations, communication và scribe có trách nhiệm tách biệt và handoff rõ.","Contain|Dừng bleeding bằng pause publication, rollback, quarantine hoặc serve-last-known-good nhưng bảo toàn evidence.","Diagnose|Dựng timeline và hypotheses từ facts; phân biệt trigger, contributing conditions và latent controls.","Recover and validate|Khôi phục service/data rồi đối soát completeness, correctness và downstream restatement trước close.","Communicate learn follow-up|Cập nhật stakeholders, viết blameless postmortem, giao action owner/deadline và kiểm hiệu quả sau triển khai.")),
make_lesson(289,"Lesson_289-repair-backfill-and-restatement","Repair, backfill and restatement","wiki.data-quality.repair-backfill-restatement","Chọn repair, backfill hay restatement dựa trên corrupted scope và consumer-visible history ra sao?",(IM,GX),(IML,GXL),a(
"Scope the defect|Xác định first/last bad interval, affected keys, transformations, consumers và authoritative correction source.","Repair modes|In-place repair phù hợp state giới hạn; backfill tái xử lý intervals; rebuild/restatement thay candidate rộng hơn.","Version pinning|Ghi code, config, source snapshot và reference data version dùng cho correction; latest không mặc nhiên đúng lịch sử.","Isolation|Chạy vào candidate hoặc partition staging, giới hạn concurrency và bảo vệ daily path.","Reconcile and publish|So key sets, totals, hashes và consumer invariants; publish có atomicity hoặc explicit partial-state protocol.","Notify and lineage|Restatement cần consumer notification, correction version, old/new lineage, rerun dependencies và closure evidence.")),
make_lesson(290,"Lesson_290-false-positives-coverage-and-quality-debt","False positives, coverage and quality debt","wiki.data-quality.false-positive-coverage-debt","Đo false positives, coverage và quality debt thế nào để việc giảm noise không biến thành mất bảo vệ?",(SM,GX),(SML,GXL),a(
"Label outcomes|Mỗi alert cần disposition: true issue, expected change, duplicate, rule defect, data unavailable hay unknown.","Precision and coverage|Precision cao không chứng minh coverage; inventory critical assets/invariants và map rule nào bảo vệ chúng.","Debt taxonomy|Thiếu rule, stale threshold, unknown owner, expensive scan, untriaged failures và blind spot là loại debt khác nhau.","Risk prioritization|Ưu tiên theo consumer impact, occurrence likelihood, detectability, recovery cost và evidence confidence.","Safe tuning|Thay threshold bằng backtest/shadow and holdout; suppress có scope/expiry, không xóa lịch sử failure.","Debt burn-down|Theo dõi age, owner, escaped defects, alert load và coverage change; đóng debt chỉ khi control thay thế đã được chứng minh.")),
)
QUERIES={n:[f"L{n} reliability contract là gì?",f"L{n} operational evidence nào?",f"L{n} changed constraint nào?"] for n in range(286,291)}
VERIFY={n:"Replay một cửa sổ có good/bad events hoặc incident state, tính lại metric độc lập và kiểm action/routing đúng policy." for n in range(286,291)}
TAKEAWAYS={286:"Data SLI đo trải nghiệm consumer trên population có thể kiểm lại.",287:"Alert là yêu cầu hành động; error budget là cơ chế quyết định theo SLO.",288:"Incident lifecycle cần roles, live state, containment, validated recovery và follow-up.",289:"Correction chỉ hoàn tất khi phạm vi, version, reconciliation và consumer restatement đều rõ.",290:"Giảm noise không được đánh đổi coverage mà không công bố risk."}
SOURCES=((SM,"1_Nguon/Web/SRC-GOOGLE-SRE-MONITORING.md","https://sre.google/sre-book/monitoring-distributed-systems/","Google SRE - Monitoring Distributed Systems","Monitoring vocabulary, actionable alerting and black-box versus white-box signals."),(EB,"1_Nguon/Web/SRC-GOOGLE-SRE-ERROR-BUDGET-POLICY.md","https://sre.google/workbook/error-budget-policy/","Google SRE - Example Error Budget Policy","Error-budget goals, calculation, policy actions and non-punitive reliability control."),(IM,"1_Nguon/Web/SRC-GOOGLE-SRE-INCIDENT-MANAGEMENT.md","https://sre.google/sre-book/managing-incidents/","Google SRE - Managing Incidents","Incident roles, command post, live state, handoff, recovery and preparedness."))
if __name__=="__main__": raise SystemExit(run_batch(lessons=LESSONS,queries=QUERIES,verification=VERIFY,takeaways=TAKEAWAYS,sources=SOURCES,version="1.0.57",timestamp="2026-10-02T23:59:57+07:00"))
